style.css:
@-moz-document domain("roblox.com") {
/* 1. Set the main background image */
    body {
        /* *** PASTE YOUR IMAGE URL HERE (between the quotes) *** */
        background: url("https://i.pinimg.com/1200x/38/0d/8d/380d8d5577a8a0cb43886d32b1e931bd.jpg") no-repeat fixed center top / cover !important;
    }

    /* 2. Make the site's content areas transparent so the image shows through */
    .content,
    .container-main,
    .section-content,
    .card-item,
    .notification-stream-wrap,
    .popover,
    .dropdown-menu,
    .rbx-tabs-horizontal .nav-tabs > li.active > a, 
    .rbx-tabs-horizontal .nav-tabs > li.active > a:hover,
    .rbx-tabs-horizontal .nav-tabs > li.active > a:focus
    {
        background-color: transparent !important;
    }

    /* Optional: Adjust text color for better readability over a dark background */
    body, h1, h2, h3, h4, .text-nav, .text-name, .text-label, .text-footer {
        color: #ffffff !important; /* Change to a light color like white or light gray */
        text-shadow: 1px 1px 2px #000000 !important; /* Optional: adds a black outline to text */
    }
}
